-- JobPortal database for MySQL / MariaDB (generated by tools/build_sql.py)
-- Import in MySQL Workbench: File > Open SQL Script > run (lightning icon).
-- WARNING: this script DROPS and re-creates the tables.
-- Sample logins: password for every account is  Password@123

CREATE DATABASE IF NOT EXISTS job_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE job_portal;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `applications`;
DROP TABLE IF EXISTS `seeker_skills`;
DROP TABLE IF EXISTS `jobs`;
DROP TABLE IF EXISTS `experience`;
DROP TABLE IF EXISTS `education`;
DROP TABLE IF EXISTS `job_seekers`;
DROP TABLE IF EXISTS `companies`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `skills`;

CREATE TABLE skills (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(60) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	`role` VARCHAR(20) NOT NULL, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_role ON users (`role`);

CREATE TABLE companies (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	company_name VARCHAR(200) NOT NULL, 
	logo VARCHAR(255), 
	cover_image VARCHAR(255), 
	description TEXT, 
	industry VARCHAR(120), 
	company_size VARCHAR(30), 
	founded_year INTEGER, 
	website VARCHAR(255), 
	email VARCHAR(255), 
	phone VARCHAR(30), 
	address VARCHAR(255), 
	city VARCHAR(100), 
	state VARCHAR(100), 
	country VARCHAR(100), 
	linkedin_url VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE INDEX ix_companies_company_name ON companies (company_name);
CREATE INDEX ix_companies_industry ON companies (industry);

CREATE TABLE job_seekers (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	profile_image VARCHAR(255), 
	headline VARCHAR(200), 
	phone VARCHAR(30), 
	location VARCHAR(150), 
	about TEXT, 
	linkedin_url VARCHAR(255), 
	github_url VARCHAR(255), 
	portfolio_url VARCHAR(255), 
	resume_path VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE education (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	seeker_id INTEGER NOT NULL, 
	institution VARCHAR(200) NOT NULL, 
	degree VARCHAR(150) NOT NULL, 
	field_of_study VARCHAR(150), 
	start_year INTEGER, 
	end_year INTEGER, 
	description TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(seeker_id) REFERENCES job_seekers (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE INDEX ix_education_seeker_id ON education (seeker_id);

CREATE TABLE experience (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	seeker_id INTEGER NOT NULL, 
	company_name VARCHAR(200) NOT NULL, 
	job_title VARCHAR(150) NOT NULL, 
	start_date DATE, 
	end_date DATE, 
	description TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(seeker_id) REFERENCES job_seekers (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE INDEX ix_experience_seeker_id ON experience (seeker_id);

CREATE TABLE jobs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	company_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT NOT NULL, 
	requirements TEXT, 
	responsibilities TEXT, 
	location VARCHAR(150) NOT NULL, 
	employment_type VARCHAR(30) NOT NULL, 
	experience_required INTEGER NOT NULL, 
	salary_min INTEGER, 
	salary_max INTEGER, 
	skills VARCHAR(500), 
	deadline DATE, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(company_id) REFERENCES companies (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE INDEX ix_jobs_company_id ON jobs (company_id);
CREATE INDEX ix_jobs_status_created ON jobs (status, created_at);
CREATE INDEX ix_jobs_title ON jobs (title);

CREATE TABLE seeker_skills (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	seeker_id INTEGER NOT NULL, 
	skill_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_seeker_skill UNIQUE (seeker_id, skill_id), 
	FOREIGN KEY(seeker_id) REFERENCES job_seekers (id) ON DELETE CASCADE, 
	FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE applications (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	job_id INTEGER NOT NULL, 
	seeker_id INTEGER NOT NULL, 
	resume_path VARCHAR(255), 
	cover_letter TEXT, 
	status VARCHAR(20) NOT NULL, 
	applied_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_application_job_seeker UNIQUE (job_id, seeker_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE, 
	FOREIGN KEY(seeker_id) REFERENCES job_seekers (id) ON DELETE CASCADE
)ENGINE=InnoDB CHARSET=utf8mb4;
CREATE INDEX ix_applications_job_id ON applications (job_id);
CREATE INDEX ix_applications_seeker_id ON applications (seeker_id);
CREATE INDEX ix_applications_status ON applications (status);

