-- jobs: 15 rows
INSERT INTO `jobs` (`id`, `company_id`, `title`, `description`, `requirements`, `responsibilities`, `location`, `employment_type`, `experience_required`, `salary_min`, `salary_max`, `skills`, `deadline`, `status`, `created_at`, `updated_at`) VALUES
  (1, 1, 'Python Developer', 'TechVista Solutions is hiring a Python Developer to join our Pune team. You will work with Python and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Python, FastAPI, MySQL\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Python\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Pune, Maharashtra', 'Full Time', 1, 500000, 800000, 'Python, FastAPI, MySQL', '2026-11-20', 'active', '2026-10-04 05:40:15', '2026-10-06 05:40:15'),
  (2, 1, 'Full Stack Developer', 'TechVista Solutions is hiring a Full Stack Developer to join our Pune team. You will work with Python and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Python, JavaScript, HTML, CSS, MySQL\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Python\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Pune, Maharashtra', 'Full Time', 2, 800000, 1400000, 'Python, JavaScript, HTML, CSS, MySQL', '2026-11-20', 'active', '2026-10-01 05:40:15', '2026-10-06 05:40:15'),
  (3, 1, 'QA Automation Engineer', 'TechVista Solutions is hiring a QA Automation Engineer to join our Pune team. You will work with Selenium and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Selenium, Java, Postman, SQL\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Selenium\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Pune, Maharashtra', 'Full Time', 2, 600000, 1000000, 'Selenium, Java, Postman, SQL', '2026-11-20', 'active', '2026-09-27 05:40:15', '2026-10-06 05:40:15'),
  (4, 2, 'Frontend Developer (React)', 'CloudNine Systems is hiring a Frontend Developer (React) to join our Bangalore team. You will work with React and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of React, JavaScript, Tailwind CSS\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using React\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Bangalore, Karnataka', 'Full Time', 1, 600000, 1100000, 'React, JavaScript, Tailwind CSS', '2026-11-20', 'active', '2026-10-05 05:40:15', '2026-10-06 05:40:15'),
  (5, 2, 'DevOps Engineer', 'CloudNine Systems is hiring a DevOps Engineer to join our Bangalore team. You will work with Docker and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Docker, AWS, CI/CD, Linux\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Docker\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Bangalore, Karnataka', 'Full Time', 3, 1200000, 2000000, 'Docker, AWS, CI/CD, Linux', '2026-11-20', 'active', '2026-09-29 05:40:15', '2026-10-06 05:40:15'),
  (6, 2, 'Cloud Support Associate', 'CloudNine Systems is hiring a Cloud Support Associate to join our Remote team. You will work with Linux and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Linux, AWS, Communication\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Linux\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Remote', 'Remote', 0, 300000, 500000, 'Linux, AWS, Communication', '2026-11-20', 'active', '2026-10-03 05:40:15', '2026-10-06 05:40:15'),
  (7, 3, 'Java Backend Developer', 'FinEdge Technologies is hiring a Java Backend Developer to join our Mumbai team. You will work with Java and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of Java, Spring Boot, Hibernate, MySQL\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using Java\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Mumbai, Maharashtra', 'Full Time', 3, 1000000, 1800000, 'Java, Spring Boot, Hibernate, MySQL', '2026-11-20', 'active', '2026-10-02 05:40:15', '2026-10-06 05:40:15'),
  (8, 3, 'Business Analyst', 'FinEdge Technologies is hiring a Business Analyst to join our Mumbai team. You will work with SQL and related technologies, collaborate with designers and product managers and ship features that matter to our customers.', 'Working knowledge of SQL, Excel, Requirement Analysis\nDegree in Computer Science, IT, BCA, MCA or equivalent\nGood communication and problem-solving skills\nEagerness to learn new tools', 'Design, build and maintain features using SQL\nWrite clean, tested and well-documented work\nCollaborate with the team in daily stand-ups and reviews\nTroubleshoot issues and continuously improve quality', 'Mumbai, Maharashtra', 'Full Time', 2, 700000, 1200000, 'SQL, Excel, Requirement Analysis', '2026-11-20', 'active', '2026-09-24 05:40:15', '2026-10-06 05:40:15'),
